# My test input
test_input = [
    [0, 5, 5, 0, 5, 0],
    [0, 5, 0, 0, 0, 5],
    [5, 0, 5, 0, 5, 0],
    [5, 5, 5, 0, 0, 0],
    [0, 5, 0, 5, 5, 5],
    [0, 0, 5, 0, 5, 0]
]

def rot90cw(grid):
    n = len(grid)
    return [[grid[n-1-j][i] for j in range(n)] for i in range(n)]

def rot180(grid):
    return rot90cw(rot90cw(grid))

def rot270cw(grid):
    return rot90cw(rot90cw(rot90cw(grid)))

# Compute the four quadrants
tl = test_input  # top-left = original
tr = rot90cw(test_input)  # top-right
bl = rot270cw(test_input)  # bottom-left
br = rot180(test_input)  # bottom-right

# Construct the output grid
height, width = len(test_input), len(test_input[0])
output = [[0]*(2*width) for _ in range(2*height)]

# Top-left
for i in range(height):
    for j in range(width):
        output[i][j] = tl[i][j]

# Top-right
for i in range(height):
    for j in range(width):
        output[i][width+j] = tr[i][j]

# Bottom-left
for i in range(height):
    for j in range(width):
        output[height+i][j] = bl[i][j]

# Bottom-right
for i in range(height):
    for j in range(width):
        output[height+i][width+j] = br[i][j]

print("Output grid (12x12):")
for row in output:
    print(row)

print("\nAs JSON:")
import json
print(json.dumps(output))
